package solution

import (
	"errors"
	"strings"
)

type InventoryItem struct {
	Code      string
	Name      string
	CostCents int64
	Group     string
	Notes     string
}

type InventoryPatch struct {
	Name      *string
	CostCents *int64
	Group     *string
	Notes     *string
}

func UpdateInventoryItem(table map[string]InventoryItem, code string, patch InventoryPatch) (InventoryItem, error) {
	item, exists := table[code]
	if code == "" {
		if exists {
			return item, errors.New("empty code")
		}
		return InventoryItem{}, errors.New("empty code")
	}
	if !exists {
		return InventoryItem{}, errors.New("item not found")
	}

	updated := item
	if patch.Name != nil {
		if strings.TrimSpace(*patch.Name) == "" {
			return item, errors.New("invalid name")
		}
		updated.Name = *patch.Name
	}
	if patch.CostCents != nil {
		if *patch.CostCents < 0 {
			return item, errors.New("negative cost")
		}
		updated.CostCents = *patch.CostCents
	}
	if patch.Group != nil {
		if strings.TrimSpace(*patch.Group) == "" {
			return item, errors.New("invalid group")
		}
		updated.Group = *patch.Group
	}
	if patch.Notes != nil {
		updated.Notes = *patch.Notes
	}

	table[code] = updated
	return updated, nil
}
